//! Every command through the real binary, end to end (M3 step 9): keys, init, pack, `feed add`
//! and `refresh`, `verify` and `inspect`, on the layout of an ordinary non-Rust app. Keys are
//! generated by the binary at test time, and every command's output is scanned for every secret
//! generated so far.
//!
//! The feeds and key sets the binary wrote are also read back in-test with the core verifiers
//! (never trusting the binary's own `verify` alone).

mod common;

use std::cell::RefCell;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Output;

use common::*;
use ed25519_dalek::SigningKey;
use ed25519_dalek::pkcs8::DecodePrivateKey;
use lunepack_core::{
    AppId, Channel, Clock, ClockReading, RollbackFloor, TrustedRoot, VerifiedFeed, VerifiedKeySet,
    verify_feed, verify_key_set,
};
use lunepack_crypto::{Ed25519Verifier, Sha256Hasher};
use lunepack_testkit::exe_headers;

const APP: &str = "org.example.hello";
const T0: u64 = 1_800_000_000;
const DAY: u64 = 86_400;
const WIN: &str = "windows-x86_64";

struct At(u64);

impl Clock for At {
    fn now_unix_secs(&self) -> u64 {
        self.0
    }
}

struct Key {
    path: PathBuf,
    public: String,
}

fn s(path: &Path) -> &str {
    path.to_str().expect("utf-8 path")
}

fn hex(text: &str) -> [u8; 32] {
    let bytes: Vec<u8> = (0..32)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).unwrap())
        .collect();
    bytes.try_into().unwrap()
}

fn spec(k: &Key) -> String {
    format!("file:{}", s(&k.path))
}

/// A second and third target that every host can pack: Unix hosts take the Linux ones, a Windows
/// host cannot pack them (M3-D10).
fn other_targets() -> Vec<&'static str> {
    if cfg!(windows) {
        vec!["windows-aarch64"]
    } else {
        vec!["linux-x86_64", "linux-aarch64"]
    }
}

struct World {
    dir: tempfile::TempDir,
    config: PathBuf,
    root: Key,
    release: Vec<Key>,
    secrets: RefCell<Vec<Vec<u8>>>,
}

impl World {
    fn new(release_keys: usize) -> World {
        let dir = tempfile::tempdir().unwrap();
        let mut w = World {
            config: dir.path().join("lunepack.toml"),
            root: Key {
                path: PathBuf::new(),
                public: String::new(),
            },
            release: Vec::new(),
            secrets: RefCell::new(Vec::new()),
            dir,
        };
        w.root = w.new_key("root");
        w.release = (0..release_keys)
            .map(|i| w.new_key(&format!("release{i}")))
            .collect();
        let out = w.run(
            &["init", "--app-id", APP, "--root-key", &w.root.public],
            &[],
        );
        assert_ok(&out, "init");
        w
    }

    fn cmd(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let output = run(args, env);
        let secrets = self.secrets.borrow();
        let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
        assert_no_secrets(&output, &refs);
        output
    }

    fn run(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let mut full = vec!["--config", s(&self.config)];
        full.extend_from_slice(args);
        self.cmd(&full, env)
    }

    /// Like [`World::run`] with `SOURCE_DATE_EPOCH` set to `epoch`.
    fn run_at(&self, epoch: u64, args: &[&str]) -> Output {
        self.run(args, &[("SOURCE_DATE_EPOCH", &epoch.to_string())])
    }

    fn new_key(&self, name: &str) -> Key {
        let base = self.dir.path().join(name);
        let out = self.cmd(&["keys", "gen", s(&base)], &[]);
        assert_ok(&out, "keys gen");
        let path = base.with_extension("key");
        let pem = fs::read_to_string(&path).unwrap();
        let seed = SigningKey::from_pkcs8_pem(&pem).unwrap().to_bytes();
        let mut secrets = self.secrets.borrow_mut();
        secrets.push(pem.into_bytes());
        secrets.push(seed.to_vec());
        Key {
            path,
            public: field(&stdout(&out), "public:"),
        }
    }

    /// A release dir with `keys.json` (the listed release keys, threshold 1) written at `T0`.
    fn release_dir(&self, name: &str, keys: &[&Key]) -> PathBuf {
        let dir = self.dir.path().join(name);
        fs::create_dir(&dir).unwrap();
        self.keys_set(&dir, keys);
        dir
    }

    fn keys_set(&self, dir: &Path, keys: &[&Key]) {
        let mut args = vec!["keys", "set", "--release-dir", s(dir)];
        for k in keys {
            args.extend_from_slice(&["--release-key", &k.public]);
        }
        let root = spec(&self.root);
        args.extend_from_slice(&["--sign", &root]);
        assert_ok(&self.run_at(T0, &args), "keys set");
    }

    fn pack(&self, input: &Path, dir: &Path, version: &str, target: &str, key: &Key) -> Output {
        self.pack_signed(input, dir, version, target, &[key])
    }

    fn pack_signed(
        &self,
        input: &Path,
        dir: &Path,
        version: &str,
        target: &str,
        keys: &[&Key],
    ) -> Output {
        let signers: Vec<String> = keys.iter().map(|k| spec(k)).collect();
        let mut args = vec![
            "pack",
            "--input",
            s(input),
            "--version",
            version,
            "--target",
            target,
            "--release-dir",
            s(dir),
        ];
        for signer in &signers {
            args.extend_from_slice(&["--sign", signer]);
        }
        self.run_at(T0, &args)
    }

    fn feed(
        &self,
        verb: &str,
        dir: &Path,
        version: Option<&str>,
        key: &Key,
        epoch: u64,
        extra: &[&str],
    ) -> Output {
        let signer = spec(key);
        let mut args = vec![
            "feed",
            verb,
            "--release-dir",
            s(dir),
            "--channel",
            "stable",
            "--sign",
            &signer,
        ];
        if let Some(v) = version {
            args.extend_from_slice(&["--version", v]);
        }
        args.extend_from_slice(extra);
        self.run_at(epoch, &args)
    }

    fn verify(&self, dir: &Path, at: Option<u64>) -> Output {
        let at = at.map(|t| t.to_string());
        let mut args = vec!["verify", s(dir)];
        if let Some(t) = &at {
            args.extend_from_slice(&["--at", t]);
        }
        self.run(&args, &[])
    }

    fn keys(&self, dir: &Path) -> VerifiedKeySet {
        let root = TrustedRoot::from_parts(
            AppId::parse(APP).unwrap(),
            1,
            1,
            &[hex(&self.root.public)],
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .unwrap();
        verify_key_set(
            &root,
            &fs::read(dir.join("keys.json")).unwrap(),
            &RollbackFloor::default(),
            &ClockReading::read(&At(T0), None),
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .expect("keys.json verifies")
    }

    /// The feed the binary wrote, read back with the core verifier, time checks skipped.
    fn read_feed(&self, dir: &Path) -> VerifiedFeed {
        verify_feed(
            &self.keys(dir),
            &fs::read(dir.join("feed-stable.json")).unwrap(),
            &AppId::parse(APP).unwrap(),
            &Channel::parse("stable").unwrap(),
            &RollbackFloor::default(),
            &ClockReading::read(&At(T0), Some(u64::MAX)),
            &Ed25519Verifier,
        )
        .expect("the feed verifies")
    }
}

/// Deterministic noise (xorshift64), incompressible.
fn noise(seed: u64, len: usize) -> Vec<u8> {
    let mut x = seed | 1;
    (0..len)
        .map(|_| {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            (x >> 24) as u8
        })
        .collect()
}

fn text(len: usize) -> Vec<u8> {
    b"The quick brown fox jumps over the lazy dog; pack me small.\n"
        .iter()
        .copied()
        .cycle()
        .take(len)
        .collect()
}

fn write(root: &Path, rel: &str, bytes: &[u8]) {
    let path = root.join(rel);
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, bytes).unwrap();
}

/// An ordinary non-Rust app's build output (M3-D13): no symlink, no Cargo file.
fn app_tree() -> tempfile::TempDir {
    let input = tempfile::tempdir().unwrap();
    let root = input.path();
    write(root, "MyApp.exe", &exe_headers::pe(0x8664, 48 * 1024));
    write(
        root,
        "lib/libfoo.so",
        &exe_headers::elf(183, false, 32 * 1024),
    );
    write(root, "bin/helper.dll", &exe_headers::pe(0xAA64, 32 * 1024));
    let mut png = vec![0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
    png.extend(noise(7, 4_000));
    write(root, "assets/logo.png", &png);
    write(
        root,
        "assets/data.json",
        &br#"{"name": "MyApp", "items": [1, 2, 3]}"#.repeat(40),
    );
    write(root, "assets/fonts/ui/Regular.txt", &text(3_000));
    write(root, "README.txt", &text(2_000));
    input
}

fn copy_dir(from: &Path, to: &Path) {
    fs::create_dir_all(to).unwrap();
    for e in fs::read_dir(from).unwrap() {
        let e = e.unwrap();
        let dest = to.join(e.file_name());
        if e.file_type().unwrap().is_dir() {
            copy_dir(&e.path(), &dest);
        } else {
            fs::copy(e.path(), dest).unwrap();
        }
    }
}

/// Flips one bit in the middle of the file.
fn flip(path: &Path) {
    let mut bytes = fs::read(path).unwrap();
    let at = bytes.len() / 2;
    bytes[at] ^= 1;
    fs::write(path, bytes).unwrap();
}

/// A packed release `version` of `targets` and a `stable` feed listing them, all signed by the
/// first release key.
struct Released {
    w: World,
    input: tempfile::TempDir,
    dir: PathBuf,
}

fn released(version: &str, targets: &[&str]) -> Released {
    let w = World::new(1);
    let input = app_tree();
    let dir = w.release_dir("rel", &[&w.release[0]]);
    for t in targets {
        assert_ok(&w.pack(input.path(), &dir, version, t, &w.release[0]), t);
    }
    assert_ok(
        &w.feed("add", &dir, Some(version), &w.release[0], T0, &[]),
        "feed add",
    );
    Released { w, input, dir }
}

/// Test 1: the full flow.
#[test]
fn full_flow() {
    let other = other_targets()[0];
    let r = released("4.0.0", &[WIN, other]);
    let w = &r.w;
    let out = w.verify(&r.dir, Some(T0));
    assert_ok(&out, "verify");
    let log = stdout(&out);
    for t in [WIN, other] {
        assert!(
            log.contains(&format!("4.0.0/{t}.manifest.json: manifest and pack ok")),
            "{log}"
        );
    }
    assert!(log.contains("feed-stable.json"), "{log}");

    let out = w.run(
        &["inspect", s(&r.dir), "--at", &T0.to_string(), "--entries"],
        &[],
    );
    assert_ok(&out, "inspect");
    let shown = stdout(&out);
    for t in [WIN, other] {
        assert!(shown.contains(&format!("    {t}:")), "{shown}");
    }
    assert!(shown.contains("release 4.0.0: rollout everyone, 2 target(s)"));
    assert!(
        shown.contains("feed stable (feed-stable.json): seq"),
        "{shown}"
    );
    assert!(shown.contains("threshold 1"), "{shown}");
    let codec_of = |path: &str| -> String {
        let line = shown
            .lines()
            .find(|l| l.trim_start().starts_with(&format!("{path}  file")))
            .unwrap_or_else(|| panic!("no entry line for {path}: {shown}"));
        line.split("codec ")
            .nth(1)
            .and_then(|r| r.split_whitespace().next())
            .unwrap()
            .to_owned()
    };
    assert!(["bcj-x86+lzma2", "bcj2"].contains(&codec_of("MyApp.exe").as_str()));
    assert_eq!(codec_of("lib/libfoo.so"), "bcj-arm64+lzma2");
    assert_eq!(codec_of("bin/helper.dll"), "bcj-arm64+lzma2");
    assert_eq!(codec_of("assets/logo.png"), "stored");
    assert_eq!(codec_of("README.txt"), "lzma2");
    assert!(shown.contains("assets/fonts/ui  dir"), "{shown}");

    // The filters pick what they name, and an unknown target is a usage-level failure.
    let out = w.run(
        &[
            "inspect",
            s(&r.dir),
            "--at",
            &T0.to_string(),
            "--target",
            WIN,
        ],
        &[],
    );
    assert_ok(&out, "inspect --target");
    assert!(!stdout(&out).contains(&format!("    {other}:")));
    let out = w.run(&["inspect", s(&r.dir), "--target", "plan9-mips"], &[]);
    assert_fails(&out, 1, "inspect with an unknown target");
    drop(r.input);
}

/// Test 2: one tampered byte or a missing file, each on its own copy of the release dir.
#[test]
fn tampering_fails_verify() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    assert_ok(&w.verify(&r.dir, Some(T0)), "untouched copy source");

    let cases: [(&str, &str); 6] = [
        ("pack frame byte", "4.0.0/windows-x86_64.pack"),
        (
            "manifest payload byte",
            "4.0.0/windows-x86_64.manifest.json",
        ),
        ("feed byte", "feed-stable.json"),
        ("keys.json byte", "keys.json"),
        ("deleted pack", "4.0.0/windows-x86_64.pack"),
        ("deleted manifest", "4.0.0/windows-x86_64.manifest.json"),
    ];
    for (i, (what, file)) in cases.iter().enumerate() {
        let copy = w.dir.path().join(format!("tampered-{i}"));
        copy_dir(&r.dir, &copy);
        let path = copy.join(file);
        if what.starts_with("deleted") {
            fs::remove_file(&path).unwrap();
        } else {
            flip(&path);
        }
        let out = w.verify(&copy, Some(T0));
        let err = assert_fails(&out, 1, what);
        assert!(err.starts_with("error: "), "{what}: {err:?}");
        if what.starts_with("deleted") {
            assert!(err.contains("does not exist"), "{what}: {err:?}");
        }
        // inspect refuses to show anything from the same copy.
        let out = w.run(&["inspect", s(&copy), "--at", &T0.to_string()], &[]);
        assert_fails(&out, 1, what);
        assert!(
            stdout(&out).is_empty(),
            "{what}: inspect printed {:?}",
            stdout(&out)
        );
    }
    assert_ok(&w.verify(&r.dir, Some(T0)), "the original is untouched");
}

/// Test 3: an expired feed fails `verify`; `feed refresh` at the later time fixes it.
#[test]
fn expiry_and_refresh() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let later = T0 + 400 * DAY;
    let out = w.verify(&r.dir, Some(later));
    let err = assert_fails(&out, 1, "verify 400 days later");
    assert!(err.contains("expired"), "{err:?}");
    // First-install floors: the same directory at the issue time is fine.
    assert_ok(
        &w.verify(&r.dir, Some(T0 + DAY)),
        "verify a day after issue",
    );

    assert_ok(
        &w.feed("refresh", &r.dir, None, &w.release[0], later, &[]),
        "feed refresh at +400 days",
    );
    assert_ok(&w.verify(&r.dir, Some(later)), "verify after the refresh");
    let feed = w.read_feed(&r.dir);
    assert_eq!(feed.issued(), later);
    assert_eq!(feed.expires(), Some(later + 90 * DAY));
}

/// Test 4: `seq` rises with every write, also within one second.
#[test]
fn seq_strictly_increases() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let first = w.read_feed(&r.dir).seq();
    assert_eq!(first, T0 * 1000);
    let mut seqs = vec![first];
    for _ in 0..2 {
        assert_ok(
            &w.feed("refresh", &r.dir, None, &w.release[0], T0, &[]),
            "feed refresh",
        );
        seqs.push(w.read_feed(&r.dir).seq());
    }
    assert!(seqs.windows(2).all(|p| p[0] < p[1]), "{seqs:?}");
    // add -> refresh -> refresh, then add again in the same second.
    let t = other_targets()[0];
    assert_ok(
        &w.pack(r.input.path(), &r.dir, "4.0.0", t, &w.release[0]),
        t,
    );
    assert_ok(
        &w.feed("add", &r.dir, Some("4.0.0"), &w.release[0], T0, &[]),
        "feed add",
    );
    let last = w.read_feed(&r.dir).seq();
    assert!(last > *seqs.last().unwrap());
}

/// Test 5: adding targets of a listed release keeps the earlier references byte-identical.
#[test]
fn adding_targets_keeps_references() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let reference = |feed: &VerifiedFeed, t: &str| {
        let release = &feed.releases()[0];
        let c = release
            .targets()
            .iter()
            .find(|(k, _)| k.as_str() == t)
            .map(|(_, c)| c.clone())
            .unwrap_or_else(|| panic!("no {t} in the feed"));
        (c.path().to_owned(), c.size(), c.sha256())
    };
    let mut listed = vec![WIN.to_owned()];
    let mut before = vec![reference(&w.read_feed(&r.dir), WIN)];
    for t in other_targets() {
        assert_ok(
            &w.pack(r.input.path(), &r.dir, "4.0.0", t, &w.release[0]),
            t,
        );
        // Packed but not listed yet.
        let out = w.verify(&r.dir, Some(T0));
        assert_ok(&out, "verify with an unreferenced manifest");
        assert!(
            stdout(&out).contains(&format!("4.0.0/{t}.manifest.json: unreferenced")),
            "{}",
            stdout(&out)
        );
        assert_ok(
            &w.feed("add", &r.dir, Some("4.0.0"), &w.release[0], T0, &[]),
            "feed add of a new target",
        );
        let feed = w.read_feed(&r.dir);
        assert_eq!(feed.releases().len(), 1);
        for (t0, b) in listed.iter().zip(&before) {
            assert_eq!(&reference(&feed, t0), b, "{t0} changed");
        }
        listed.push(t.to_owned());
        before.push(reference(&feed, t));
        assert_ok(&w.verify(&r.dir, Some(T0)), "verify");
    }
    assert_eq!(
        w.read_feed(&r.dir).releases()[0].targets().len(),
        listed.len()
    );
    assert!(!stdout(&w.verify(&r.dir, Some(T0))).contains(": unreferenced"));
}

/// A release dir whose manifest is signed by both release keys and whose feed by the first only;
/// then the first key is revoked.
fn revoked_world() -> (World, PathBuf) {
    let w = World::new(2);
    let (a, b) = (&w.release[0], &w.release[1]);
    let input = app_tree();
    let dir = w.release_dir("rel", &[a, b]);
    assert_ok(
        &w.pack_signed(input.path(), &dir, "4.0.0", WIN, &[a, b]),
        "pack",
    );
    assert_ok(&w.feed("add", &dir, Some("4.0.0"), a, T0, &[]), "feed add");
    assert_ok(&w.verify(&dir, Some(T0)), "verify before the revocation");

    w.keys_set(&dir, &[b]);
    let out = w.verify(&dir, Some(T0));
    let err = assert_fails(&out, 1, "verify after the revocation");
    assert!(err.contains("feed-stable.json does not verify"), "{err:?}");
    // The revoked key can no longer sign anything new.
    let out = w.pack(input.path(), &dir, "4.0.1", WIN, a);
    let err = assert_fails(&out, 1, "pack with the revoked key");
    assert!(err.contains("not in keys.json"), "{err:?}");
    (w, dir)
}

/// Test 6: revoking the release key (`keys set` without it).
#[test]
fn revocation() {
    revoked_world();
}

/// Test 6, second half: `feed refresh` with the remaining key repairs the feed. Blocked: the
/// writer reads the previous feed through `verify_feed`, which the revoked signature fails, so
/// there are no releases to carry over (see notes.md, step 9).
#[test]
#[ignore = "blocked: refresh cannot read a feed signed by a revoked key; needs a decision"]
fn revocation_then_refresh() {
    let (w, dir) = revoked_world();
    assert_ok(
        &w.feed("refresh", &dir, None, &w.release[1], T0 + DAY, &[]),
        "feed refresh with the new key",
    );
    assert_ok(&w.verify(&dir, Some(T0 + DAY)), "verify after the refresh");
}

/// Writer refusals of `feed add`.
#[test]
fn feed_add_refusals() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let key = &w.release[0];

    // No manifest for the version.
    let out = w.feed("add", &r.dir, Some("9.9.9"), key, T0, &[]);
    assert_fails(&out, 1, "feed add of an unpacked version");

    // A version of equal precedence under other text.
    let twin = r.dir.join("4.0.0+b");
    copy_dir(&r.dir.join("4.0.0"), &twin);
    let out = w.feed("add", &r.dir, Some("4.0.0+b"), key, T0, &[]);
    let err = assert_fails(&out, 1, "equal precedence");
    assert!(err.contains("equal precedence"), "{err:?}");
    fs::remove_dir_all(&twin).unwrap();

    // A listed manifest is never replaced by different bytes.
    let t = other_targets()[0];
    assert_ok(&w.pack(r.input.path(), &r.dir, "4.0.0", t, key), t);
    fs::copy(
        r.dir.join(format!("4.0.0/{t}.manifest.json")),
        r.dir.join("4.0.0/windows-x86_64.manifest.json"),
    )
    .unwrap();
    let out = w.feed("add", &r.dir, Some("4.0.0"), key, T0, &[]);
    let err = assert_fails(&out, 1, "a replaced manifest");
    assert!(err.contains("never replaced"), "{err:?}");

    // refresh needs an existing feed; the signer must be in keys.json.
    let fresh = w.release_dir("fresh", &[key]);
    let out = w.feed("refresh", &fresh, None, key, T0, &[]);
    assert_fails(&out, 1, "refresh without a feed");
    let stranger = w.new_key("stranger");
    let out = w.feed("add", &r.dir, Some("4.0.0"), &stranger, T0, &[]);
    assert_fails(&out, 1, "feed add with a key outside keys.json");
}

/// A widened rollout keeps the release's seed.
#[test]
fn rollout_keeps_its_seed() {
    let w = World::new(1);
    let input = app_tree();
    let key = &w.release[0];
    let dir = w.release_dir("rel", &[key]);
    assert_ok(&w.pack(input.path(), &dir, "4.0.0", WIN, key), "pack");
    assert_ok(
        &w.feed("add", &dir, Some("4.0.0"), key, T0, &["--rollout", "1000"]),
        "feed add --rollout 1000",
    );
    let first = w.read_feed(&dir).releases()[0].rollout().unwrap();
    assert_eq!(first.basis_points, 1000);
    // Without a flag, a re-add keeps the rollout; with one, only the share changes.
    assert_ok(&w.feed("refresh", &dir, None, key, T0, &[]), "refresh");
    assert_eq!(w.read_feed(&dir).releases()[0].rollout().unwrap(), first);
    assert_ok(
        &w.feed("add", &dir, Some("4.0.0"), key, T0, &["--rollout", "10000"]),
        "feed add --rollout 10000",
    );
    let wide = w.read_feed(&dir).releases()[0].rollout().unwrap();
    assert_eq!((wide.basis_points, wide.seed), (10_000, first.seed));
    let out = w.verify(&dir, Some(T0));
    assert_ok(&out, "verify");
    let out = w.run(&["inspect", s(&dir), "--at", &T0.to_string()], &[]);
    assert!(
        stdout(&out).contains("rollout 10000 of 10000"),
        "{}",
        stdout(&out)
    );
}
